<script lang="ts">
  import {searchableSelect} from '#lib/client/searchable-select.ts';
  import {refreshAll} from '$app/navigation';import {command,display,recordName} from '#lib/client/api.ts';import type {AppData,Row} from '#lib/client/types.ts';import Icon from './Icon.svelte';import Status from './Status.svelte';
  let {data}:{data:AppData}=$props();let open=$state(false);let mode=$state('access');let contactName=$state('');let password=$state('');let identity=$state('individual_session');let expires=$state('');let accessId=$state('');let busy=$state(false);let error=$state('');let notice=$state('');let createdUrl=$state('');let confirmed=$state(false);let revoking:Row|null=$state(null);let revokeConfirmed=$state(false);
  const record=$derived(data.detail||{});const customerId=$derived(data.module?.slug==='customers'?record.id:record.customer_id||data.summary?.portalCustomerId);const accesses=$derived(data.related?.portal_accesses||[]);const accessLookup=$derived(data.lookups?.['portal-accesses']||accesses.filter(a=>!a.revoked_at).map(a=>({id:a.id,name:a.contact_name||a.name||'Freigegebener Zugang'})));
  async function copyLink(){error='';try{await navigator.clipboard.writeText(createdUrl);notice='Der Portal-Link wurde kopiert. Übermitteln Sie das Passwort separat über den vorgesehenen Weg.';}catch{error='Der Browser erlaubt das Kopieren gerade nicht. Markieren Sie den Link im Feld und kopieren Sie ihn manuell.';}}
  async function createAccess(event:SubmitEvent){event.preventDefault();busy=true;error='';notice='';try{const result=await command('portal.access.create',undefined,{customer_id:customerId,contact_name:contactName,password,identity_assurance:identity,expires_at:expires?new Date(expires+'T23:59:59').toISOString():undefined});password='';createdUrl=result.url||result.portal_url||(result.token?new URL(`/portal/${result.token}`,window.location.origin).href:'');notice='Der Portalzugang wurde angelegt. Übermitteln Sie Link und Passwort über den betrieblich vorgesehenen Weg.';await refreshAll().catch(()=>{});}catch(e){error=e instanceof Error?e.message:'Der Portalzugang konnte nicht angelegt werden.';}finally{busy=false;}}
  async function revoke(event:SubmitEvent){event.preventDefault();if(!revoking||!revokeConfirmed)return;busy=true;error='';notice='';try{await command('portal.access.revoke',revoking.id,{},revoking.version);revoking=null;revokeConfirmed=false;notice='Der Portalzugang und seine bestehenden Sitzungen wurden widerrufen.';await refreshAll().catch(()=>{});}catch(e){error=e instanceof Error?e.message:'Der Zugang konnte nicht widerrufen werden.';}finally{busy=false;}}
  async function publish(event:SubmitEvent){event.preventDefault();if(!confirmed)return;busy=true;error='';notice='';try{await command('portal.publish',undefined,{portal_access_id:accessId,entity_type:({quotes:'quote',invoices:'invoice',documents:'document',deliveries:'delivery',acceptances:'acceptance'} as Record<string,string>)[data.module?.slug||''],entity_id:record.id,revision_id:record.revision_id||undefined,document_version_id:data.summary?.portalDocumentVersionId||record.current_version_id||undefined});notice='Der angezeigte Stand wurde ausdrücklich für diesen Portalzugang veröffentlicht.';confirmed=false;await refreshAll().catch(()=>{});}catch(e){error=e instanceof Error?e.message:'Der Stand konnte nicht veröffentlicht werden.';}finally{busy=false;}}
</script>
<section class="panel"><header class="panel-header"><h2>Kundenportal</h2><button class="btn small" onclick={()=>open=!open}>{open?'Schließen':'Verwalten'}<Icon name="lock" size={14}/></button></header><div class="panel-body"><p class="small">Kunden sehen ausschließlich bewusst veröffentlichte Inhalte und konkrete Versionen.</p>{#each accesses as access}<div class="integration-row"><div><h3>{access.contact_name||'Freigegebener Kundenzugang'}</h3><p>{access.identity_assurance==='shared_access'?'Gemeinsamer Zugang':'Benannter Kontakt'}{access.expires_at?` · Bis ${display(access.expires_at,'expires_at')}`:''}</p></div><div class="stack" style="gap:10px;align-items:flex-end"><Status value={access.revoked_at?'blocked':'active'}/>{#if !access.revoked_at}<button class="btn small" disabled={busy} onclick={()=>{open=true;revoking=access;revokeConfirmed=false;}}>Widerrufen</button>{/if}</div></div>{/each}{#if open}<div class="tabs mt"><button class="tab" class:active={mode==='access'} onclick={()=>mode='access'}>Zugang einrichten</button>{#if ['quotes','invoices','documents','deliveries','acceptances'].includes(data.module?.slug||'')}<button class="tab" class:active={mode==='publish'} onclick={()=>mode='publish'}>Diesen Stand teilen</button>{/if}</div>{#if error}<div class="notice error" role="alert">{error}</div>{/if}{#if notice}<div class="notice info" role="status">{notice}</div>{/if}{#if createdUrl}<div class="field mb"><label for="created-portal-link">Einmalig bereitgestellter Portal-Link</label><input id="created-portal-link" value={createdUrl} readonly/><button type="button" class="btn mt" onclick={copyLink}>Portal-Link kopieren<Icon name="link" size={15}/></button><a class="text-link mt" href={createdUrl} target="_blank" rel="noreferrer">Portal öffnen<Icon name="arrow" size={14}/></a></div>{/if}{#if revoking}<form onsubmit={revoke} class="form-section mb"><h3>Zugang von {revoking.contact_name||'diesem Kontakt'} widerrufen?</h3><p class="small mt">Dieser Zugang kann anschließend keine Veröffentlichungen mehr öffnen. Bestehende Portalsitzungen werden beendet. Veröffentlichungs- und Entscheidungsnachweise bleiben erhalten.</p><label class="check-field mt"><input type="checkbox" bind:checked={revokeConfirmed} required/><span>Ich möchte genau diesen Portalzugang widerrufen.</span></label><div class="inline-actions mt"><button type="button" class="btn" disabled={busy} onclick={()=>revoking=null}>Zurück</button><button class="btn danger" disabled={busy||!revokeConfirmed}>Portalzugang widerrufen</button></div></form>{/if}{#if mode==='access'}{#if customerId}<form onsubmit={createAccess}><div class="field mb"><label for="portal-contact">Kontaktperson / Gruppe *</label><input id="portal-contact" bind:value={contactName} required/></div><div class="field mb"><label for="portal-identity">Zugangsart *</label><select use:searchableSelect={identity} id="portal-identity" bind:value={identity}><option value="individual_session">Benannter Kontaktzugang</option><option value="shared_access">Gemeinsamer Kundenzugang</option></select></div><div class="field mb"><label for="portal-new-password">Neues Portalpasswort *</label><input id="portal-new-password" type="password" bind:value={password} autocomplete="new-password" minlength="15" required/><span class="field-help">Mindestens 15 Zeichen. Verwenden Sie ein eigenes Portalpasswort und notieren Sie es vor dem Anlegen. Das gespeicherte Passwort wird später nicht wieder angezeigt.</span></div><div class="field"><label for="portal-expiry">Optional befristet bis</label><input id="portal-expiry" type="date" bind:value={expires}/></div><button class="btn primary full mt" disabled={busy}>{busy?'Wird angelegt …':'Zugang anlegen'}</button></form>{:else}<p class="small">Für diesen Vorgang ist noch kein Kunde zugeordnet. Richten Sie den Zugang in der passenden Kundenakte ein, sobald die Zuordnung bestätigt ist.</p>{/if}{:else}<form onsubmit={publish}><div class="action-preview"><h3>{recordName(record)}</h3><p class="small">Version {record.version||'—'} · {data.module?.singular}</p><p class="small mt">Veröffentlichung dieses ausdrücklich bezeichneten Stands. Interne Kalkulation und Personaldaten bleiben geschützt.</p></div><div class="field"><label for="portal-access-select">Empfangender Portalzugang *</label><select use:searchableSelect={accessId} id="portal-access-select" bind:value={accessId} required><option value="">Zugang auswählen</option>{#each accessLookup as access}<option value={access.id}>{access.name}</option>{/each}</select></div>{#if !accessLookup.length}<p class="field-help mt">Es ist noch kein nutzbarer Zugang zugeordnet.</p>{/if}<label class="check-field mt"><input type="checkbox" bind:checked={confirmed} required/><span>Ich habe Inhalt, Version und Empfänger geprüft und möchte genau diesen Stand veröffentlichen.</span></label><button class="btn primary full mt" disabled={busy||!confirmed||!accessId}>Stand bewusst veröffentlichen</button></form>{/if}{/if}</div></section>
